#include <bits/stdc++.h>using namespace std;int main() {    int t;    cin >> t;    while (t--) {        int n;        cin >> n;        vector<int> a(n);        for (int i = 0; i < n; i++) {            cin >> a[i];        }        long long ans = 0;        int x = 0;        for (int i = 0; i < n; i++) {            x = max(x, a[i]);            ans += x;        }        for (int i = 0; i < n; i++) {            for (int j = i + 1; j < n; j++) {                swap(a[i], a[j]);                long long s = 0;                int x = 0;                for (int k = 0; k < n; k++) {                    x = max(x, a[k]);                    s += x;                }                ans = max(ans, s);                swap(a[i], a[j]);            }        }        cout << ans << endl;    }}